format:
.v-card-item__content {
    display: none;
}
.v-tab-item--selected {
    color: #0094ce !important;
}
.v-card .remove,
.v-card-text .remove {
    display: none !important;
    visibility: hidden;
    color: transparent !important;
}
.v-main {
    padding-bottom: 2em;
}
#app-bar-actions img {
    margin-right: 20px;
}
.ui-title span {
    font-size: 1.4rem !important;
    font-weight: normal !important;
    padding: 0;
    color: #0094ce;
}
.ui-spacer {
    border-top: 2px solid #CCCCCC;
}
.nrdb-ui-group {
    border-radius: 4px;
    box-shadow: 3px 2px 2px rgba(0, 55, 77, 0.25);
}
.oe_nav {
    background: rgb(var(--v-theme-navigation-background));
}
#oe_header {
    border: none;
    padding-left: 1em;
    background: rgb(var(--v-theme-navigation-background));
}
.v-application {
    border-top: 1px solid #CCCCCC;
    margin-top: -1px;
}

func:
// Keep up to date reverse links

function inverse(obj) {
  let retobj = { };
  for(var key in obj) {
    retobj[obj[key]] = key;
  }

  return retobj;
}

global.set('rlink', {}, 'memoryOnly');
global.set('rlink', inverse(global.get('kernel.link', 'memoryOnly')) ,'memoryOnly');

msg.payload = '';

return msg;

// Compute device watchdog value

let newMsg = {
    'kernel': {},
    'topic': '',
    'payload': ''
};

const limit = Math.round(Date.now() / 1000) - (global.get('kernel.app.watchdog', 'memoryOnly') || 120);

const devices = { ...(global.get('kernel.device', 'memoryOnly') || {}) };
for (const device in devices) {
    let watchdog = (global.get('kernel.watchdog["' + device + '"]', 'memoryOnly') || 0) < limit ? 0 : 1;

    newMsg.kernel = {
        'type': 'device',
        'entity': device,
        'value': watchdog,
        'loop': false
    };

    newMsg.telegram = {'change': false};
    if (newMsg.kernel.value !== global.get('kernel.device["' + device + '"]', 'memoryOnly')) {
        newMsg.telegram = {
            'type': 'watchdog',
            'change': true,
            'entity': device,
            'value': watchdog === 1 ? true : false
        }
    }

    node.status({ 'fill': watchdog ? 'green' : 'red', 'text': device + ' = ' + watchdog });
    node.send(newMsg);
}

return;

// Prepare influxdb message

// devices watchdogs
if (msg.kernel.type === 'device') {
    msg.measurement = msg.kernel.entity;
    msg.payload = [{'watchdog': msg.kernel.value }];

    //delete msg.kernel;

    return msg;
}

// components states
else if (msg.kernel.component !== 'cycle' || msg.kernel.value > 0) {
    msg.measurement = msg.kernel.equipment;
    msg.payload = [{[msg.kernel.component]: msg.kernel.value }];

    node.status({ 'fill': 'green', 'text': msg.kernel.equipment + ' - ' + msg.kernel.component + ' = ' + msg.kernel.value })

    delete msg.kernel;

    return msg;
}

return;

// Check that message contains login informations

if (typeof msg.login === 'string' && msg.login !== "" && typeof msg.pass === 'string' && msg.pass !== "") {
    msg.login = msg.login.toLowerCase();
    const hash = global.get('auth["' + msg.login + '"]["pass"]', 'memoryOnly');
    if (typeof hash === 'string') {
        msg.hash = hash;

        return msg;
    }
}

return msg;

// Check active users on ui

/* Limit to 6 hours */
let limit = Date.now() - (6*60*60*1000);
msg.topic = limit;

let users = global.get('user', 'memoryOnly');
if (typeof users === 'object') {
    for (const user in users) {
        if (typeof global.get('auth["' + users[user]["login"] + '"]["level"]', 'memoryOnly') !== 'string' 
        || users[user]["time"] < limit 
        || (typeof msg.login === 'string' && msg.login === users[user]["login"])
        ) {
            global.set('user["' + user + '"]', undefined, 'memoryOnly');
            global.set('form["' + user + '"]', undefined, 'memoryOnly');
            msg.payload = user;
            node.send(msg);
        }
    }
}

msg.payload = 'cleaned';

return msg;

// Parse kernel from backup

let newMsg = {
    'topic':'',
    'payload':'',
    'kernel':{
        'type':'',
        'entity':'',
        'value':'',
        'loop':true,
        'delete':false
    }
};

/* Check if payload is well formed */
if (typeof msg.payload?.app?.vendor === 'string') {
    /* Delete current kernel */
    //global.set('kernel', newMsg.kernel, 'memoryOnly');

    for (const type in msg.payload) {
        newMsg.kernel.type = type;

        for (const entity in msg.payload[type]) {
            newMsg.kernel.entity = entity;
            newMsg.kernel.value = msg.payload[type][entity];

            node.send(newMsg);
        }
    }
}

msg.payload = 'Lecture du fichier de sauvegarde terminée';

return [null,msg];

// Convert mqtt topic to kernel message

if (global.get('kernel.app.frommqtt', 'memoryOnly') === true && msg.payload !== '') {
    let tsplit = msg.topic.split('/');
    if (tsplit.length === 3 && typeof global.get('kernel["' + tsplit[1] + '"]["' + tsplit[2] + '"]', 'memoryOnly') !== 'undefined') {
        node.status({ 'fill' : 'green', 'text': tsplit[1] + ' - ' + tsplit[2] + ' = ' + msg.payload });

        return {
            'topic': '',
            'payload':' ',
            'kernel': {
                'type': tsplit[1],
                'entity': tsplit[2],
                'value': msg.payload,
                'loop': true
            }
        }
    }
}

return;

// Check ui page action

// on unwanted state, stop here
if (!['connect', 'change', 'lost'].includes(msg.payload)) {
    if (typeof msg.hmi.id === 'string' && msg.hmi.id !== '') {
        global.set('user["' + msg.hmi.id + '"]', undefined, 'memoryOnly');
        global.set('form["' + msg.hmi.id + '"]', undefined, 'memoryOnly');
    }

    return;
}

// on connect or lost connection, go to auth page
if (['connect', 'lost'].includes(msg.payload)) {
    msg.payload = global.get('describe.pages.auth.name', 'memoryOnly') || '';

    return [null, null, msg];
}

// prepare
msg.menus = {};
msg.titles = {};
msg.payload = {
    'pages': {
        'show': [],
        'hide': []
    }
};

let pages = global.get('describe.pages', 'memoryOnly');
if (typeof pages !== 'object') {
    return;
}

// check user page right
let allowed = false;
let s = 0;
let h = 0;
for (const page in pages) {
    if (typeof pages[page]['level'][msg.hmi.level] === 'boolean') {
        if (pages[page]['level'][msg.hmi.level] === true) {
            msg.menus[page] = true;
            msg.payload.pages.show[s++] = pages[page]['name'];
        } else {
            msg.menus[page] = false;
            msg.payload.pages.hide[h++] = pages[page]['name'];
        }
    } else {
        if (global.get('describe.pages.auth.tab', 'memoryOnly') === pages[page]['tab']) {
            msg.menus[page] = true;
            msg.payload.pages.show[s++] = pages[page]['name'];
        } else {
            msg.menus[page] = false;
            msg.payload.pages.hide[h++] = pages[page]['name'];
        }
    }
    msg.titles[page] = msg.dictionary.option_page[page];

    if (pages[page]['tab'] === msg.hmi.tab) {
        msg.page_lang = msg.dictionary.lang;
    }

    if (pages[page]['tab'] === msg.hmi.tab && pages[page]['level'][msg.hmi.level] === true) {
        allowed = true;
    }
}

if (allowed === false) {
    msg.hmi.tab = global.get('describe.pages.auth.tab', 'memoryOnly');
    msg.hmi.page = global.get('describe.pages.auth.name', 'memoryOnly');
}

// user plant
let form_plant = global.get('form["' + msg.hmi.id + '"]["plant"]', 'memoryOnly')||'-';
if (msg.hmi.plant !== '' && msg.hmi.plant !== form_plant) {
    global.set('form["' + msg.hmi.id + '"]["plant"]', msg.hmi.plant, 'memoryOnly');
    global.set('form["' + msg.hmi.id + '"]["line"]', '', 'memoryOnly');
    global.set('form["' + msg.hmi.id + '"]["equipment"]', '', 'memoryOnly');
}
global.set('form["' + msg.hmi.id + '"]["ts"]', Date.now(), 'memoryOnly');

// page process
let newMsg = {
    'topic': '',
    'payload': msg.hmi.page,
    'options': [{ 'label': '', 'value': '' }],
    'hmi': msg.hmi,
    'dictionary': msg.dictionary,
    '_client': msg._client
};

// ui menu
msg.version = global.get('describe.app.version', 'memoryOnly') || '0.0.0';
msg.vendor = global.get('kernel.app.vendor', 'memoryOnly') || global.get('describe.app.vendor', 'memoryOnly');
msg.title = msg.hmi.page; 
msg.document = global.get('kernel.app.title', 'memoryOnly') || global.get('describe.app.title', 'memoryOnly');
msg.full = 'OptaEquipments v' + msg.version + ' for ' + msg.vendor;

delete msg.dictionary;

return [msg, newMsg, null];

// Check ui page informations

if (msg.payload !== '' && typeof global.get('describe.pages["' + msg.payload + '"]["name"]', 'memoryOnly') === 'string') {
    msg.tab = global.get('describe.pages["' + msg.payload + '"]["tab"]', 'memoryOnly');
    msg.name = global.get('describe.pages["' + msg.payload + '"]["name"]', 'memoryOnly');
    msg.payload = msg.name;

    return msg;
} else {
    let default_browser = {
        'lang': msg.payload,
        'time': Date.now()
    }
    global.set('browser["' + msg._client.socketId + '"]', default_browser, 'memoryOnly');

    const time = Date.now() - 60000;
    let browsers = { ...(global.get('browser', 'memoryOnly') || {}) };
    for (const browser in browsers) {
        if (browsers[browser]['time'] < time) {
            delete browsers[browser];
        }
    }
    global.set('browser', browsers, 'memoryOnly');

    return;
}

// Build period loop row

/* tree */
let tsplit = msg.team.split('|');
msg.row.plant = tsplit[0];
msg.row.team = tsplit[1];

/* plant offset (dec) */
let dec = Number(global.get('kernel.day["' + msg.row.plant + '"]', 'memoryOnly') || 0);
msg.row.dectime = dec * 100; // ex: 600, in order to compare to starttime/stoptime 630, 2330...

/* team time */
let psplit = msg.payload.split('|');
msg.row.starttime = Number(psplit[0].split(':').join('')); //convert calendar time to comparable number
msg.row.stoptime = Number(psplit[1].split(':').join(''));

/* datetime formatter tz */
msg.outTz = msg.row.tz = global.get('kernel.tz["' + msg.row.plant + '"]', 'memoryOnly') || 'Europe/Paris';

return msg;

// Compute period state

msg.payload = '';

let final_teams = flow.get('teams', 'memoryOnly') || {};
let final_periods = {};
let final_pilots = {};

delete msg.row;
delete msg.settings;
delete msg.outTz;
delete msg.team;
flow.set('teams', undefined, 'memoryOnly');

const periods = { ...(global.get('kernel.period', 'memoryOnly') || {}) };
for (const line in periods) {
    final_periods[line] = false;

    /* line program is enabled */
    if (global.get('kernel.disabled["' + line + '"]', 'memoryOnly') === false) {
        /* no periods set for this line */
        if (periods[line] === '') {
            /* set to off */
            final_pilots[line] = false;
        } else {
            let exists = false;
            const plant = global.get('kernel.lines["' + line + '"]', 'memoryOnly');
            const teams = periods[line].split("");
            for (const i in teams) {
                if (typeof final_teams[plant][teams[i]] === 'boolean') {
                    exists = true;
                    if (final_teams[plant][teams[i]] === true) {
                        final_periods[line] = true;
                    }
                }
            }
            if (exists) {
                final_pilots[line] = final_periods[line];
            }
        }
    }
}

const states = { ...(global.get('kernel.state','memoryOnly')||{}) };
for (const entity in states) {
    let esplit = entity.split('|');
    let equipment = esplit[0];
    let component = esplit[1];
    let line = global.get('kernel.equipments["' + equipment + '"]', 'memoryOnly');

    let pilot = final_pilots[line];
    if (typeof pilot === 'boolean'
        && typeof global.get('kernel.link["' + entity + '"]', 'memoryOnly') === 'string'
        && component.match((new RegExp('^(heatswitch|heatlink|heattoggle|heatpulse)$'))) !== null
    ) {
        let state = global.get('kernel.state["' + equipment + '|run"]', 'memoryOnly');
        if (typeof state === 'number' && state === 1 && pilot === false) {
            /* do not pilot heat to off if equipment is running */
        } else {
            msg.kernel = {
                'type': 'state',
                'entity': entity,
                'value': pilot === true ? 1 : 0,
                'loop': false
            };

            msg.telegram = {
                'type': 'period',
                'value': pilot,
                'entity': equipment,
                'change': msg.kernel.value !== states[entity]
            };

            if (component === 'heatpulse') {
                /* pulse only if current state is not the one we want */
                if (msg.kernel.value !== global.get('kernel.state["' + equipment + '|heat"]', 'memoryOnly')) {
                    /* pulse */
                    msg.kernel.value = 1;
                    node.send(msg);
                    await new Promise(resolve => setTimeout(resolve, 500));
                    msg.kernel.value = 0;
                    delete msg.telegram;
                    node.send(msg);
                }
            } else {
                node.send(msg);
            }

            node.status({ 'fill': pilot ? 'green' : 'red', 'text': entity + ' = ' + pilot });
        }
    }
}

return;

// Compute loop message

delete msg.qos;
delete msg.retain;

/* Node counter */
/*
let ctx = (context.get('count','memoryOnly')||0)+1;
context.set('count',ctx,'memoryOnly');
node.status({'text':ctx});
//*/

/* check kernel message */
if (typeof msg.kernel === 'object'
    && typeof msg.kernel.type === 'string'
    && typeof msg.kernel.entity === 'string'
    && typeof msg.kernel.value !== 'undefined'
    && typeof msg.kernel.loop === 'boolean'
) {
    /* deletion requested */
    if (typeof msg.kernel.delete === 'boolean' && msg.kernel.delete === true) {
        global.set('kernel["' + msg.kernel.type + '"]["' + msg.kernel.entity + '"]', undefined, 'memoryOnly');
    } else {
        let current = global.get('kernel["' + msg.kernel.type + '"]["' + msg.kernel.entity + '"]', 'memoryOnly');
        /* new value is not the same as existing */
        //if (current !== msg.kernel.value) {
            //msg.kernel.loop = false;
            /* update kernel value */
            global.set('kernel["' + msg.kernel.type + '"]["' + msg.kernel.entity + '"]', msg.kernel.value, 'memoryOnly');
        //}

        delete msg.kernel.model;
        if (msg.kernel.type === 'state') {
            // For kernel state, retrieve component definition
            let target = global.get('kernel.link["' + msg.kernel.entity + '"]', 'memoryOnly');
            if (typeof target === 'string') {
                let csplit = msg.kernel.entity.split("|");
                msg.kernel.equipment = csplit[0];
                msg.kernel.component = csplit[1];

                let tsplit = target.split("|");
                msg.kernel.model = tsplit[0];
                msg.kernel.device = tsplit[1];
                msg.kernel.terminal = tsplit[2];
                msg.kernel.convert = global.get('describe.convert["' + msg.kernel.model + '"]["' + msg.kernel.component + '"]','memoryOnly')||'';

                // Mirror components repeat input state to output
                let mirror = msg.kernel.equipment + '|' + msg.kernel.component + 'mirror';
                let link = global.get('kernel.link["' + mirror + '"]', 'memoryOnly');
                if (typeof link === 'string') {
                    let mirrorMsg = {
                        'topic': '',
                        'payload': '',
                        'kernel': {
                            'type': msg.kernel.type,
                            'entity': mirror,
                            'value': msg.kernel.value,
                            'loop': false
                        }
                    };

                    node.status({ 'fill': 'blue', 'text': msg.kernel.type + ' - ' + msg.kernel.equipment + ' - ' + msg.kernel.component + ' = ' + msg.kernel.value });

                    node.send([null, null, null, mirrorMsg]);
                }
            }
        }

        let newMsg = {
            'topic': '',
            'payload': '',
            'kernel': msg.kernel
        };

        node.status({ 'fill': msg.kernel.loop === false ? 'green' : 'yellow', 'text': msg.kernel.type + ' - ' + msg.kernel.equipment + ' - ' + msg.kernel.component + ' = ' + msg.kernel.value });

        return [
            // to kernel MQTT loop
            msg.kernel.loop === false ? newMsg : null,
            // to device loop
            typeof msg.kernel.model === 'string' && msg.kernel.loop === false ? newMsg : null,
            // to db
            typeof msg.kernel.model === 'string' ? newMsg : null,
            // mirror
            null
        ];
    }
}

return;

// Perpare mqtt message

if (global.get('kernel.app.tomqtt', 'memoryOnly') === true) {
    return  {
        'topic': [(global.get('describe.app.automate', 'default') || 'optaequipments'), msg.kernel.type, msg.kernel.entity].join('/'),
        'payload': msg.kernel.value,
        'qos': 0,
        'retain': msg.kernel?.delete === true ? true : false
    };
}

return;

// Parse users backup

flow.set('has_admin', false, 'memoryOnly');

if (typeof msg.payload === 'object') {
    for (const login in msg.payload) {
        if (typeof msg.payload[login]["pass"] === 'string'
            && typeof msg.payload[login]["pass"] === 'string'
            && typeof msg.payload[login]["plant"] === 'string'
            && typeof msg.payload[login]["level"] === 'string'
        ) {
            if (typeof msg.payload[login]["lang"] !== 'string') {
                msg.payload[login]["lang"] = 'fr';
            }
            if (typeof msg.payload[login]["telegram"] !== 'string') {
                msg.payload[login]["telegram"] = '';
            }

            if (msg.payload[login]["level"] === 'admin') {
                flow.set('has_admin', true, 'memoryOnly');
            }

            global.set('auth["' + login + '"]', {
                'pass': msg.payload[login]["pass"],
                'level': msg.payload[login]["level"],
                'plant': msg.payload[login]["plant"],
                'lang': msg.payload[login]["lang"],
                'telegram': msg.payload[login]["telegram"]
            }, 'memoryOnly');
        }
    }
}

delete msg.automate;
delete msg.filename;

return msg;

// Prepare app context

// Set describe
global.set('describe', {
    'app': {
        'automate': 'optaequipments',
        'version': '0.6.0',
        'title': 'Live Equipments',
        'vendor': 'Opta Equipments by JcDenis'
    },
    'pages': {
        'auth': {
            'tab': 0,
            'id': '64fe17ae4a406472',
            'name': 'Authentification',
            'level': {
                'admin': true,
                'rt': true,
                'tech': true,
                'rp': true,
                'prod': true
            }
        },
        'alert': {
            'tab': 1,
            'id': 'a19160517715b70b',
            'name': 'Maintenance',
            'level': {
                'admin': true,
                'rt': true,
                'tech': true,
                'rp': true,
                'prod': true
            }
        },
        'period': {
            'tab': 2,
            'id': '4d7d40fad3a281d3',
            'name': 'Programmes',
            'level': {
                'admin': true,
                'rt': true,
                'tech': true,
                'rp': true,
                'prod': true
            }
        },
        'detail': {
            'tab': 3,
            'id': '71ccb6fab20261e2',
            'name': 'Détail',
            'level': {
                'admin': true,
                'rt': true,
                'tech': true,
                'rp': true,
                'prod': true
            }
        },
        'list':{
            'tab': 4,
            'id': '297c38d08e523a55',
            'name': 'Listes',
            'level': {
                'admin': true,
                'rt': true,
                'tech': true,
                'rp': false,
                'prod': false
            }
        },
        'tree':{
            'tab': 5,
            'id': '5287a3b059e7b4ce',
            'name': 'Arborescence',
            'level': {
                'admin': true,
                'rt': true,
                'tech': false,
                'rp': false,
                'prod': false
            }
        },
        'users': {
            'tab': 6,
            'id': 'ed8b7656d516b26d',
            'name': 'Utilisateurs',
            'level': {
                'admin': true,
                'rt': false,
                'tech': false,
                'rp': false,
                'prod': false
            }
        },
        'system': {
            'tab': 7,
            'id': '1ac335c1e0a24a11',
            'name': 'Système',
            'level': {
                'admin': true,
                'rt': false,
                'tech': false,
                'rp': false,
                'prod': false
            }
        }
    },
    'groups': {
        'run': ['run','runmeter', 'runmetertotal', 'runreset', 'runmirror'],
        'cycle': ['cycle', 'cyclemeter', 'cyclemetertotal', 'cyclereset', 'cyclemirror'],
        'heat': ['heat', 'heatswitch'],
        'uptime': ['uptime', 'load1meter', 'load5meter', 'load15meter', 'memorymeter', 'diskmeter'],
        'voltage': ['voltage', 'power']
    }
}, 'memoryOnly');

// Clear user and more
global.set('auth', {}, 'memoryOnly');
global.set('user', {}, 'memoryOnly');
global.set('form', {}, 'memoryOnly');

// Various
return {
    'topic': '',
    'payload': '',
    'options': [{ 'label':'', 'value':'' }]
};

// Backup and restore kernel to/from local file

if (msg.boot === true) {
    // on (re)boot, load kernel backup
    global.set('kernel', (global.get('kernel_bk', 'default') || {}), 'memoryOnly');
} else {
    // on cron, write kernel to backup
    global.set('kernel_bk', global.get('kernel', 'memoryOnly'), 'default');
}

delete msg.boot;

return msg;

msg.payload = msg.dictionary.option_notice.update_fail;
msg.success = false;

if (msg.hmi.level !== 'admin') {
    msg.payload = msg.dictionary.option_notice.level_fail;
} else if (typeof msg.kernel.entity === 'string' && msg.kernel.type === 'plant') {
    let is_empty = true;
    // kernel.lines
    const lines = { ...(global.get('kernel.lines', 'memoryOnly') || {}) };
    for (const line in lines) {
        if (lines[line] === msg.kernel.entity) {
            is_empty = false;
        }
    }

    if (is_empty === true) {
        // kernel.plant
        node.send([{
            'topic': '',
            'payload': '',
            'kernel': {
                'type': 'plant',
                'entity': msg.kernel.entity,
                'value': '',
                'loop': false,
                'delete': true
            }
        }]);

        // kernel.tz
        node.send([{
            'topic': '',
            'payload': '',
            'kernel': {
                'type': 'tz',
                'entity': msg.kernel.entity,
                'value': '',
                'loop': false,
                'delete': true
            }
        }]);

        // kernel.day
        node.send([{
            'topic': '',
            'payload': '',
            'kernel': {
                'type': 'day',
                'entity': msg.kernel.entity,
                'value': '',
                'loop': false,
                'delete': true
            }
        }]);

        // kernel.team
        const teams = { ...(global.get('kernel.team', 'memoryOnly') || {}) };
        for (const team in teams) {
            let tsplit = team.split('|');
            if (tsplit[0] === msg.kernel.entity) {
                node.send([{
                    'topic': '',
                    'payload': '',
                    'kernel': {
                        'type': 'team',
                        'entity': team,
                        'value': '',
                        'loop': false,
                        'delete': true
                    }
                }]);
            }
        }

        msg.payload = msg.dictionary.option_notice.update_success;
        msg.success = true;
    }
}

delete msg.kernel;

return msg;

msg.payload = msg.dictionary.option_notice.update_fail;
msg.success = false;

if (msg.hmi.level !== 'admin' && msg.hmi.id !== 'rt') {
    msg.payload = msg.dictionary.option_notice.level_fail;
} else if (typeof msg.kernel.entity === 'string' && msg.kernel.type === 'line') {
    let is_empty = true;
    // kernel.lines
    const equipments = { ...(global.get('kernel.equipments', 'memoryOnly') || {}) };
