let newMsg = {
    'topic':msg.topic,
    'payload':'',
    'kernel':{}
};

/* 0 = model, 1 = device, 2 = path, 3 = type, 4 = io : opta/2/input/high */
const split = msg.topic.split('/');

if (split[2] === 'device') {
    flow.set('devices["' + split[0] + '|' + split[1] + '"]["' + split[3] + '"]', msg.payload, 'memoryOnly');
    flow.set('devices["' + split[0] + '|' + split[1] + '"]["date"]', Date.now(), 'memoryOnly');
} else if (split[2] === 'watchdog') {
    if (split[1] !== 'distant') {
        newMsg.kernel = {
            'type': 'watchdog',
            'entity': 'opta|' + split[1],
            'value': Math.round(Date.now() / 1000),
            'loop': false
        };

        return newMsg;
    }
} else if ((split[2] === 'input' || split[2] === 'output') && split[3] !== 'set') {
    // update timer from low level on reversed state
    let low = false;
    if (split[3] === 'partialLow' || split[3] === 'low' ) {
        low = true;
        split[3] = split[3] === 'low' ? 'high' : 'partialHigh';
    }

    let link = 'opta|' + split[1] + '|' + split[4] + '|' + (split[2] === 'input' ? 'i' : 'o') + '|' + split[3];
    let endpoint = global.get('rlink["' + link + '"]', 'memoryOnly');
    if (typeof endpoint === 'string') {
        // for now limit to "run" component
        let reverse = global.get('kernel.reverse["' + endpoint.split('|')[0] + '|run"]', 'memoryOnly') || false;

        // skip low value on not reversed state
        if (low && !reverse) {
            return;
        }

        if ((low && reverse) || (!low && (split[3] === 'partialHigh' || split[3] === 'high'))) {
            /* convert timers fron seconds to hours, round to one decimal */
            msg.payload = Math.round(msg.payload / 360) / 10;
        } else if (split[3] === 'voltage') {
            /* convert mV to V, round to one decimal */
            msg.payload = Math.round(msg.payload / 100) / 10;
        }

        newMsg.kernel = {
            'type': 'state',
            'entity': endpoint,
            'value': msg.payload,
            /* Do not loop output */
            'loop': split[2] === 'output' ? true : false
        };

        return newMsg;
    }
}

return;

