function substringBefore(str, chars) {
    const index = str.indexOf(chars);
    return index === -1 ? str : str.substring(0, index);
}

if (typeof msg.payload['Monitor'] !== 'undefined') {
    /* Watchdog */
    newMsg.kernel = {
