            } else if (input.match((new RegExp('^(Analog)'))) !== null) {
                /* Analog */
                newMsg.kernel = {
                    'type': 'state',
                    'entity': component,
                    'value': Number(substringBefore(msg.payload.Monitor[input][0], 'V')),
                    'loop': false
                }

