if (msg.hmi.level === 'admin' || msg.hmi.level === 'rt') {
    let form = flow.get('form["' + msg.hmi.id + '"]', 'memoryOnly') || {};
    let groups = global.get('describe.groups["' + form.group + '"]', 'memoryOnly') || {};
    for (const group in groups) {
        let component = groups[group];
        let device = global.get('describe.convert["' + form.model + '"]["' + component + '"]', 'memoryOnly');
        if (typeof device === 'string') {
            let terminal = form.input;
            let reverse = form.input_reverse;
            if (component.match((new RegExp('^(heatswitch|runmirror|cyclemirror)$'))) !== null) {
                terminal = form.output;
                reverse = form.output_reverse;
            }
            if (terminal >= 0) {
                let rlink = [form.model, form.device, terminal.toString(), device].join('|');
                let entity = form.equipment + '|' + component;

                // state
                let stateMsg = {
                    'topic': '',
                    'payload': '',
                    'kernel': {
                        'type': 'state',
                        'entity': entity,
                        'value': 0,
                        'loop': false
                    }
                };
                node.send([stateMsg, null]);

                // link
                let linkMsg = {
                    'topic': '',
                    'payload': '',
                    'kernel': {
                        'type': 'link',
                        'entity': entity,
                        'value': rlink,
                        'loop': false
                    }
                };
                node.send([linkMsg, null]);

                // reverse
                if (component.match((new RegExp('^(heat|run|cycle|heatswitch|runmirror|cyclemirror)$'))) !== null) {
                    let reverseMsg = {
                        'topic': '',
                        'payload': '',
                        'kernel': {
                            'type': 'reverse',
                            'entity': entity,
                            'value': reverse,
                            'loop': false
                        }
                    };
                    node.send([reverseMsg, null]);
                }
            }
        }
    }

    // notice
    msg.payload = msg.dictionary.option_notice.update_success;
    node.send([null, msg]);
}

return;

