msg.row.session_color = msg.dictionary.option_color.off;

let users = global.get('user', 'memoryOnly') || {};
for (const user in users) {
    if (users[user]["login"] === msg.row.login) {
        msg.row.session = user;
        msg.row.session_color = msg.dictionary.option_color.on;
    }
}

return msg;

if (typeof msg.payload === 'object') {
    for (const login in msg.payload) {
        if (typeof msg.payload[login]["pass"] === 'string'
            && typeof msg.payload[login]["pass"] === 'string'
            && typeof msg.payload[login]["plant"] === 'string'
            && typeof msg.payload[login]["level"] === 'string'
            && typeof global.get('auth["' + login + '"]["level"]', 'memoryOnly') !== 'string'
        ) {
            if (typeof msg.payload[login]["lang"] !== 'string') {
                msg.payload[login]["lang"] = 'fr';
            }
            if (typeof msg.payload[login]["telegram"] !== 'string') {
                msg.payload[login]["telegram"] = '';
            }

            if (msg.payload[login]["level"] === 'admin') {
                flow.set('has_admin', true, 'memoryOnly');
            }

            global.set('auth["' + login + '"]',{
                'pass':msg.payload[login]["pass"],
                'level':msg.payload[login]["level"],
                'plant':msg.payload[login]["plant"],
                'lang': msg.payload[login]["lang"],
                'telegram': msg.payload[login]["telegram"]
            }, 'memoryOnly');
        }
    }

    msg.payload = '';
    delete msg.file;

    return msg;
}

return;

msg.check = env.get('NR_FLOW_NAME');

delete msg.ui_update;

return msg;

return {
    'topic':'',
    'payload':'',
    'kernel':{
        'type':'app',
        'entity':'icon',
        'value':msg.payload,
        'loop':false
    }
};

return {
    'topic':'',
    'payload':'',
    'kernel':{
        'type':'app',
        'entity':'title',
        'value':msg.payload.title,
        'loop':false
    }
};

return {
    'topic':'',
    'payload':'',
    'kernel':{
        'type':'app',
        'entity':'vendor',
        'value':msg.payload.vendor,
        'loop':false
    }
};

return {
    'topic':'',
    'payload':'',
    'kernel':{
        'type':'app',
        'entity':'tomqtt',
        'value':msg.payload.tomqtt,
        'loop':false
    }
};

return {
    'topic':'',
    'payload':'',
    'kernel':{
        'type':'app',
        'entity':'frommqtt',
        'value':msg.payload.frommqtt,
        'loop':false
    }
};

return {
    'topic':'',
    'payload':'',
    'kernel':{
        'type':'app',
        'entity':'watchdog',
        'value':Number(msg.payload.watchdog),
        'loop':false
    }
};

// reset
flow.set('kernel["' + msg.hmi.id + '"]', {}, 'memoryOnly');

// ui
msg.options = [];
msg.class = '';
msg.enabled = true;

// get kernel types
let types = global.get('kernel', 'memoryOnly');
let i = 0;
for (const type in types) {
    msg.options[i++] = {
        'label':type,
        'value':type,
    };
}

return msg;

if (msg.payload !== '') {
    // set type
    flow.set('kernel["' + msg.hmi.id + '"]["type"]', msg.payload, 'memoryOnly');
    flow.set('kernel["' + msg.hmi.id + '"]["entity"]', '', 'memoryOnly');

    // get kernel entitites
    let entities = global.get('kernel["' + msg.payload + '"]', 'memoryOnly');
    msg.options = [];
    let i = 0;
    for (const entity in entities) {
        msg.options[i++] = {
            'label':entity,
            'value':entity,
        };
    }

    // ui
    msg.class = '';
    msg.enabled = true;

    return msg;
}

return;

if (msg.payload !== '') {
    flow.set('kernel["' + msg.hmi.id + '"]["entity"]', msg.payload, 'memoryOnly');

    // ui
    msg.class = '';
    msg.enabled = true;

    return msg;
}

return;

msg.kernel = {
    'type':flow.get('kernel["' + msg.hmi.id + '"]["type"]', 'memoryOnly')||'',
    'entity':flow.get('kernel["' + msg.hmi.id + '"]["entity"]', 'memoryOnly'),
    'value':'',
    'loop':false,
    'delete':true
};

return msg;

msg.topic = '';
msg.payload = msg.dictionary.option_notice.update_success;

return msg;
